import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BvlN9b-o.js";const f=JSON.parse('{"title":"Variable Sources and Scope","description":"","frontmatter":{"docLocale":"en","counterpart":"/reference/configuration-sources","contentType":"reference","prev":false,"next":false},"headers":[],"relativePath":"en/reference/configuration-sources.md","filePath":"en/reference/configuration-sources.md"}'),d={name:"en/reference/configuration-sources.md"};function n(c,e,s,i,l,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="variable-sources-and-scope" tabindex="-1">Variable Sources and Scope <a class="header-anchor" href="#variable-sources-and-scope" aria-label="Permalink to &quot;Variable Sources and Scope&quot;">​</a></h1><p>Classify configuration by its reader. API and Worker variables and defaults belong in <a href="./config">Generated server configuration</a>, sourced from the <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/apps/api/src/bin/config-reference.rs" target="_blank" rel="noreferrer">Rust configuration exporter</a>. This page does not duplicate those defaults. Adding a server setting updates its owning <code>FIELDS</code>, reader and <code>.env.example</code>; documentation checks detect missing example keys.</p><h2 id="api-and-worker" tabindex="-1">API and Worker <a class="header-anchor" href="#api-and-worker" aria-label="Permalink to &quot;API and Worker&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable family</th><th>Reader</th><th>Scope / boundary</th></tr></thead><tbody><tr><td>Database, binding, authentication, files and upload limits</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/platform/src/config.rs" target="_blank" rel="noreferrer">Settings / AuthSettings / FileLimits</a></td><td>Validated at startup; production APP_ORIGIN is the trusted browser origin, not an internal API container URL</td></tr><tr><td>Worker binding, leases, heartbeats and shutdown</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/jobs/worker.rs" target="_blank" rel="noreferrer">WorkerPolicy / FIELDS</a></td><td>Worker process; API and Worker share database and object storage settings</td></tr><tr><td>Cache and rate limits</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/platform/src/cache.rs" target="_blank" rel="noreferrer">Cache</a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/rate_limit/mod.rs" target="_blank" rel="noreferrer">RateLimiter</a></td><td>Construct and share instances at API startup; policy determines Redis outage behavior</td></tr><tr><td>SMTP, mail encryption and password recovery</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/platform/src/mail.rs" target="_blank" rel="noreferrer">Mail settings</a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/identity/password_reset/mod.rs" target="_blank" rel="noreferrer">PasswordReset</a></td><td>API/Worker need matching key versions; deployment supplies production secrets</td></tr><tr><td>Telemetry queues, endpoints and timeouts</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/platform/src/telemetry/settings.rs" target="_blank" rel="noreferrer">TelemetrySettings</a></td><td>Bounded API/Worker exports; process EnvFilter reads <code>RUST_LOG</code></td></tr></tbody></table><p>The knowledge reference domain owns <code>EXPORT_*</code>, read by <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/knowledge/exports/configuration.rs" target="_blank" rel="noreferrer">ExportPolicy</a>. Its manifest removes this configuration when the domain is removed. Define a separate policy for your ticket exports.</p><h2 id="local-development-and-containers" tabindex="-1">Local Development and Containers <a class="header-anchor" href="#local-development-and-containers" aria-label="Permalink to &quot;Local Development and Containers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variables</th><th>Source</th><th>Purpose and limits</th></tr></thead><tbody><tr><td><code>POSTGRES_PASSWORD</code>, <code>POSTGRES_PORT</code>, <code>REDIS_PORT</code>, <code>RUSTFS_PORT</code>, <code>MAILPIT_SMTP_PORT</code>, <code>MAILPIT_HTTP_PORT</code></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/compose.yaml" target="_blank" rel="noreferrer">compose.yaml</a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/.env.example" target="_blank" rel="noreferrer">.env.example</a></td><td>Development container credentials and host ports; not frontend configuration</td></tr><tr><td><code>WEB_PORT</code>, <code>VITE_API_PROXY</code></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/apps/web/vite.config.ts" target="_blank" rel="noreferrer">Web Vite configuration</a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/scripts/dev.mjs" target="_blank" rel="noreferrer">dev.mjs</a></td><td>Local binding / development proxy target; browsers cannot read database URLs through them</td></tr><tr><td><code>TELEMETRY_HTTP_PORT</code>, <code>PROMETHEUS_PORT</code>, <code>LOKI_PORT</code>, <code>TEMPO_PORT</code>, <code>GRAFANA_PORT</code></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/scripts/lib/observability.mjs" target="_blank" rel="noreferrer">Observability scripts</a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/compose.observability.yaml" target="_blank" rel="noreferrer">Compose configuration</a></td><td>Ports for optional local observability dependencies</td></tr><tr><td><code>CARGO_BUILD_JOBS</code></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/scripts/lib/process.mjs" target="_blank" rel="noreferrer">Development process helpers</a>, Cargo</td><td>Build concurrency; affects compilation resources rather than business runtime</td></tr></tbody></table><p><code>developmentEnv()</code> uses Node&#39;s dotenv parser and merges <code>.env.example</code> → untracked <code>.env</code> → process environment, with later values winning. When local mail capture is configured without an encryption key, the <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/scripts/lib/development-mail-key.mjs" target="_blank" rel="noreferrer">development key helper</a> creates a protected machine-local file. Documentation builds never read it. Direct <code>cargo run</code> does not apply this merge; use the task runner.</p><p>Change only the corresponding <code>*_PORT</code> in <code>.env</code>. The development environment reader derives <code>DATABASE_URL</code> from <code>POSTGRES_USER</code>, <code>POSTGRES_PASSWORD</code>, <code>POSTGRES_DB</code> and its port, and also derives Redis/S3 endpoints, <code>APP_BIND</code>, <code>WORKER_BIND</code>, <code>APP_ORIGIN</code>, <code>VITE_API_PROXY</code>, the desktop origin and SMTP port. Explicit derived variables remain supported for external services; remove obsolete explicit endpoints from an older <code>.env</code> before expecting port changes to propagate. Host defaults use higher ports; container-internal ports retain their native values.</p><p>Both <code>just services-up</code> and <code>just dev</code> check host listeners and Docker published ports before startup, then verify actual bindings. <code>compose.yaml</code> has no fixed project name: the development entry derives the container, volume and network namespace from the directory name and a digest of its full path. After copying an existing project, allocate new <code>.env</code> ports; copies created by the scaffold already have independent ports.</p><h2 id="browser-and-desktop" tabindex="-1">Browser and Desktop <a class="header-anchor" href="#browser-and-desktop" aria-label="Permalink to &quot;Browser and Desktop&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variables</th><th>Source</th><th>Scope</th></tr></thead><tbody><tr><td><code>VITE_DOCS_URL</code></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/apps/web/src/main.tsx" target="_blank" rel="noreferrer">Documentation entry settings</a></td><td>Public documentation URL compiled by Vite into the browser; use public addresses only</td></tr><tr><td><code>SAAS_DESKTOP_ORIGIN</code>, <code>SAAS_DESKTOP_DOWNLOADS_DIR</code>, <code>SAAS_DESKTOP_USER_DATA_DIR</code></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/apps/desktop/src/main.ts" target="_blank" rel="noreferrer">Electron main</a></td><td>Desktop page entry, download and user-data directories; API does not read them</td></tr></tbody></table><p>Vite-prefixed values may enter public bundles. Database passwords, Session secrets, API Keys, SMTP passwords and mail encryption keys must never use <code>VITE_</code> names or appear in client source.</p><h2 id="documentation-publication-and-deployment" tabindex="-1">Documentation Publication and Deployment <a class="header-anchor" href="#documentation-publication-and-deployment" aria-label="Permalink to &quot;Documentation Publication and Deployment&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variables</th><th>Source</th><th>Purpose</th></tr></thead><tbody><tr><td><code>GITHUB_REPOSITORY</code>, <code>DOCS_BASE</code></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/apps/docs/.vitepress/config.mts" target="_blank" rel="noreferrer">VitePress configuration</a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/scripts/check-docs-build.mjs" target="_blank" rel="noreferrer">Built-link check</a></td><td>Repository URL / deployment subpath; repository name determines the default base</td></tr><tr><td><code>DOCS_SOURCE_REF</code></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/scripts/lib/docs.mjs" target="_blank" rel="noreferrer">Documentation projector</a></td><td>Source links and footer revision; defaults to Git HEAD. The footer does not prove every tutorial command ran</td></tr><tr><td><code>ENV_FILE</code> plus production hostname, ports and database credentials</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/deploy/production/env.production.example" target="_blank" rel="noreferrer">Production environment example</a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/compose.production.yaml" target="_blank" rel="noreferrer">Production compose</a></td><td>Containers, HTTPS and protected deployment settings; documentation builds do not read them</td></tr></tbody></table><p>For an unknown variable, find its reader and category before consulting the appropriate example. Development ports and documentation publication variables do not belong in Rust Settings. See <a href="./../tutorials/single-machine-production">Deployment</a> for startup validation and HTTPS operations.</p><hr><p>Source version：<code>e87f840d6dfc</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/docs/reference/configuration-sources.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>',18)])])}const u=t(d,[["render",n]]);export{f as __pageData,u as default};
